<?php require __DIR__.'/config.php'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EARN Electronics & Phones | Kenya</title><script src="https://cdn.tailwindcss.com"></script><style>
:root{--brand:#f28c18}body{font-family:Inter,system-ui,sans-serif;background:#f5f6f8}.brand{background:var(--brand)}.brand-text{color:var(--brand)}.card{background:white;border-radius:14px;box-shadow:0 3px 15px #0f172a0b}.btn{background:var(--brand);color:white;border-radius:9px;padding:.65rem 1rem;font-weight:700}.line{border:1px solid #e5e7eb;border-radius:9px;padding:.7rem;width:100%}.product-img{height:170px;object-fit:contain;width:100%;background:#fff}.hidden{display:none!important}
</style></head><body>
<div class="bg-slate-950 text-white text-xs py-2 px-4 text-center">EARN ELECTRONICS & PHONES SHOP · Delivery across Kenya · Prices in KSh</div>
<header class="bg-white sticky top-0 z-20 shadow-sm"><div class="max-w-7xl mx-auto p-4 flex flex-wrap gap-4 items-center">
<a href="index.php" class="font-black text-xl whitespace-nowrap">EARN <span class="brand-text">ELECTRONICS</span></a>
<div class="flex-1 min-w-52 flex"><input id="q" class="line rounded-r-none" placeholder="Search phones, TVs, laptops, appliances…"><button class="btn rounded-l-none" onclick="loadProducts()">Search</button></div>
<button class="border rounded-lg px-3 py-2" onclick="showOrders()">My orders</button><button class="border rounded-lg px-3 py-2" onclick="authModal()">Account</button><button class="btn" onclick="cartModal()">Cart (<span id="cartCount">0</span>)</button>
</div></header>
<main class="max-w-7xl mx-auto p-4">
<section class="rounded-2xl p-7 md:p-10 text-white mb-5" style="background:linear-gradient(110deg,#172033,#374151 55%,#f28c18)">
<p class="uppercase tracking-widest text-sm font-bold">Smart shopping. Great value.</p><h1 class="text-3xl md:text-5xl font-black my-3">Everything tech, <span class="text-orange-300">one shop.</span></h1><p class="max-w-xl">Phones, computing, home appliances and accessories. Shop conveniently with order tracking and customer support.</p><button class="bg-white text-slate-900 rounded-lg px-5 py-3 mt-5 font-bold" onclick="document.getElementById('catalog').scrollIntoView({behavior:'smooth'})">Shop products</button>
</section>
<div class="grid md:grid-cols-[220px_1fr] gap-5"><aside class="card p-4 h-fit"><h2 class="font-black text-lg mb-3">Categories</h2><div id="categories" class="space-y-1">Loading…</div><hr class="my-4"><p class="text-xs text-slate-500">Delivery is free for orders of KSh 50,000 and above; otherwise KSh 350 (demo policy).</p></aside>
<section id="catalog"><div class="flex items-end justify-between mb-4"><div><p class="brand-text font-bold text-sm">OUR CATALOGUE</p><h2 class="text-2xl font-black">Shop electronics</h2></div><select id="sort" class="line w-auto" onchange="loadProducts()"><option value="default">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></div><p id="resultCount" class="text-sm text-slate-500 mb-3"></p><div id="products" class="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-5">Loading products…</div></section></div>
</main>
<footer class="mt-10 bg-slate-950 text-slate-300 p-8"><div class="max-w-7xl mx-auto"><b class="text-white">EARN ELECTRONICS AND PHONES SHOP</b><p class="text-sm mt-2">Kenyan electronics storefront demo. Product images, prices and specifications should be verified before real sales.</p><p class="text-xs mt-3">Demo payment methods are not connected to M-Pesa or a card processor.</p></div></footer>
<div id="modal" class="hidden fixed inset-0 z-50 bg-black/50 p-3 items-center justify-center"><div class="bg-white rounded-2xl p-5 w-full max-w-xl max-h-[90vh] overflow-auto"><div class="flex justify-between items-center mb-4"><h2 id="modalTitle" class="font-black text-xl">Details</h2><button onclick="closeModal()" class="text-2xl">×</button></div><div id="modalBody"></div></div></div>
<div id="toast" class="hidden fixed bottom-5 right-5 bg-slate-950 text-white rounded-lg p-4 z-50"></div>
<script>
let products=[],cats=[],cart=JSON.parse(localStorage.getItem('earnsCart')||'[]'),user=null,csrf='';
const money=n=>'KSh '+Number(n||0).toLocaleString('en-KE',{maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,data=null,params=''){const opt={method:data?'POST':'GET',headers:{}};if(data){opt.headers['Content-Type']='application/json';opt.headers['X-CSRF-Token']=csrf;opt.body=JSON.stringify(data)}const r=await fetch('api.php?action='+action+params,opt);let j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Request failed');return j}
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),2800)}
function saveCart(){localStorage.setItem('earnsCart',JSON.stringify(cart));document.getElementById('cartCount').textContent=cart.reduce((a,x)=>a+x.quantity,0)}
async function init(){try{let m=await api('me');user=m.user;csrf=m.csrf;let c=await api('categories');cats=c;document.getElementById('categories').innerHTML='<button class="block text-left w-full p-2 rounded hover:bg-orange-50" onclick="chooseCat(\'All\')">All products</button>'+c.map(x=>`<button class="block text-left w-full p-2 rounded hover:bg-orange-50" onclick="chooseCat('${esc(x.category)}')">${esc(x.category)} <span class="text-xs text-slate-400">(${x.total})</span></button>`).join('');await loadProducts()}catch(e){toast(e.message)}}
function chooseCat(c){document.getElementById('q').dataset.cat=c;loadProducts()}
async function loadProducts(){let q=encodeURIComponent(document.getElementById('q').value),c=encodeURIComponent(document.getElementById('q').dataset.cat||'All');try{products=await api('products',null,'&q='+q+'&category='+c);let s=document.getElementById('sort').value;if(s==='low')products.sort((a,b)=>a.price-b.price);if(s==='high')products.sort((a,b)=>b.price-a.price);document.getElementById('resultCount').textContent=products.length+' products';document.getElementById('products').innerHTML=products.map(p=>`<article class="card overflow-hidden flex flex-col"><button onclick="details(${p.id})" class="p-3"><img class="product-img" loading="lazy" src="${esc(p.image_url)}" alt="${esc(p.title)}" onerror="this.src='assets/product-placeholder.svg'"></button><div class="p-4 pt-0 flex flex-col flex-1"><p class="text-xs text-slate-500">${esc(p.brand)} · ${esc(p.category)}</p><button class="text-left font-semibold my-2 leading-snug" onclick="details(${p.id})">${esc(p.title)}</button><p class="brand-text text-lg font-black mt-auto">${money(p.price)}</p><p class="text-xs text-slate-500 mb-3">${p.stock>0?'In stock: '+p.stock:'Out of stock'} · ★ ${Number(p.rating).toFixed(1)} (${p.review_count})</p><button class="btn w-full" ${p.stock<1?'disabled':''} onclick="addCart(${p.id})">Add to cart</button></div></article>`).join('')||'<p>No products found. Try another search.</p>'}catch(e){toast(e.message)}}
function addCart(id){let p=products.find(x=>+x.id===id);if(!p||p.stock<1)return toast('Currently out of stock');let item=cart.find(x=>x.id===id);if(item){if(item.quantity>=Math.min(20,p.stock))return toast('Maximum available quantity reached');item.quantity++}else cart.push({id:p.id,title:p.title,price:+p.price,quantity:1,image_url:p.image_url});saveCart();toast('Added to cart')}
function openModal(title,html){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=html;let m=document.getElementById('modal');m.classList.remove('hidden');m.classList.add('flex')}
function closeModal(){let m=document.getElementById('modal');m.classList.add('hidden');m.classList.remove('flex')}
function cartModal(){let total=cart.reduce((s,x)=>s+x.price*x.quantity,0),fee=total>=50000?0:350;openModal('Your shopping cart',cart.length?cart.map(x=>`<div class="flex gap-3 py-3 border-b"><img src="${esc(x.image_url)}" class="w-16 h-16 object-contain"><div class="flex-1"><b>${esc(x.title)}</b><p>${money(x.price)}</p><div class="flex gap-3 items-center"><button onclick="changeQty(${x.id},-1)">−</button>${x.quantity}<button onclick="changeQty(${x.id},1)">+</button><button class="text-red-600 ml-2" onclick="removeCart(${x.id})">Remove</button></div></div></div>`).join('')+`<p class="mt-4">Subtotal: <b>${money(total)}</b></p><p>Delivery: ${money(fee)}</p><p class="text-xl font-black my-2">Total: ${money(total+fee)}</p><button class="btn w-full mt-3" onclick="checkout()">Proceed to checkout</button>`:'<p>Your cart is empty.</p>')}
function changeQty(id,d){let x=cart.find(i=>i.id===id);if(x)x.quantity=Math.max(1,Math.min(20,x.quantity+d));saveCart();cartModal()}
function removeCart(id){cart=cart.filter(x=>x.id!==id);saveCart();cartModal()}
function checkout(){if(!cart.length)return;let t=cart.reduce((s,x)=>s+x.price*x.quantity,0);openModal('Delivery and checkout',`<p class="mb-3 text-sm text-slate-600">Subtotal ${money(t)} · Delivery ${money(t>=50000?0:350)}. Payment is cash on delivery in this demo.</p><form id="co" class="space-y-3"><input name="name" required class="line" placeholder="Full name" value="${esc(user?.name||'')}"><input name="email" type="email" required class="line" placeholder="Email" value="${esc(user?.email||'')}"><input name="phone" required class="line" placeholder="Kenyan phone number"><textarea name="address" required class="line" placeholder="Delivery address, town and directions"></textarea><button class="btn w-full">Place order</button></form>`);document.getElementById('co').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{let r=await api('create_order',{items:cart.map(x=>({id:x.id,quantity:x.quantity})),name:f.get('name'),email:f.get('email'),phone:f.get('phone'),address:f.get('address')});cart=[];saveCart();openModal('Order received',`<p>Your order reference is <b>${esc(r.order_code)}</b>.</p><p class="my-2">Total: <b>${money(r.total)}</b></p><p>Status: Pending. Keep your order reference.</p>`);loadProducts()}catch(err){toast(err.message)}}}
function authModal(kind='login'){openModal('Customer account',`<div class="flex gap-2 mb-4"><button class="btn" onclick="authModal('login')">Sign in</button><button class="border rounded-lg px-4" onclick="authModal('register')">Register</button></div><form id="authForm" class="space-y-3">${kind==='register'?'<input name="name" required class="line" placeholder="Full name">':''}<input name="email" type="email" required class="line" placeholder="Email"><input name="password" type="password" minlength="8" required class="line" placeholder="Password (8+ characters)"><button class="btn w-full">${kind==='login'?'Sign in':'Create account'}</button></form><p class="text-xs text-slate-500 mt-3">${user?'Signed in as '+esc(user.name):'Enter your email and password. EarnsStore checks your account role and routes administrators automatically.'}</p>${user?'<button class="mt-3 underline" onclick="logout()">Sign out</button>':''}`);document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{let r=await api(kind,{name:f.get('name'),email:f.get('email'),password:f.get('password')});user=r.user;csrf=r.csrf;closeModal();toast('Welcome, '+user.name);if(user.role==='admin')location.href='admin.php'}catch(err){toast(err.message)}}}
async function logout(){try{await api('logout',{});user=null;closeModal();toast('Signed out')}catch(e){toast(e.message)}}
async function showOrders(){try{if(!user)throw Error('Please sign in first');let r=await api('my_orders');openModal('My orders',r.map(o=>`<div class="border-b py-3"><b>${esc(o.order_code)}</b> · ${esc(o.status)}<p>${money(o.total)} · ${esc(o.created_at)}</p></div>`).join('')||'No orders yet.')}catch(e){authModal();toast(e.message)}}
async function details(id){let p=products.find(x=>+x.id===id);if(!p)return;openModal(p.title,`<img src="${esc(p.image_url)}" class="w-full h-52 object-contain" onerror="this.src='assets/product-placeholder.svg'"><p class="text-sm text-slate-500 my-2">${esc(p.brand)} · ${esc(p.category)}</p><p class="text-2xl brand-text font-black">${money(p.price)}</p><p class="my-3">${esc(p.description)}</p><p>Stock: ${p.stock} · Rating: ★ ${Number(p.rating).toFixed(1)} (${p.review_count} reviews)</p><button class="btn w-full mt-4" onclick="addCart(${p.id})">Add to cart</button><h3 class="font-black mt-5 mb-2">Customer reviews</h3><p class="text-sm text-slate-500">Reviews can be submitted by signed-in customers after a delivered purchase.</p><button class="border rounded-lg p-2 mt-2" onclick="reviewForm(${p.id})">Write a review</button>`)}
function reviewForm(id){if(!user){authModal();return}openModal('Write a review',`<form id="review" class="space-y-3"><select name="rating" class="line"><option value="5">★★★★★ - Excellent</option><option value="4">★★★★ - Good</option><option value="3">★★★ - Average</option><option value="2">★★ - Poor</option><option value="1">★ - Bad</option></select><textarea name="review_text" class="line" required maxlength="1000" placeholder="Your review"></textarea><button class="btn w-full">Submit review</button></form>`);document.getElementById('review').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{await api('add_review',{product_id:id,rating:+f.get('rating'),review_text:f.get('review_text')});toast('Review saved');closeModal();loadProducts()}catch(err){toast(err.message)}}}
document.getElementById('q').addEventListener('keydown',e=>{if(e.key==='Enter')loadProducts()});init();saveCart();
</script></body></html>